# R3 (b)(ii): is the syntactic group of c0 = #{b : A_i = 0 mod 4, B_i odd} (and of the a-analogue
# #{a : A_i = 0 mod 4, B_i even}) in the variety generated by good groups lying in A2A4?
# Same W-test as aabb_variety.py: M = R/R'R^2 = F_2^17 (Schreier basis), functionals on M.
# Families (all proved good in Lean, all in A2A4):
#   WR  : Z2 wr Z4 (all 4096 homs);
#   UT  : UT4(F2) (all 4096 homs);
#   FA  : every finite 2-group with abelian Frattini subgroup G'G^2 (Lean: groupHeightOne_of_frattini_abelian).
#         Its 2-generated relatively free object in A2A4 is W / Phi(W)', and Phi(W)' lies in M:
#         K_FA = (x^2 - 1)M + (y^2 - 1)M + F2[Q].[x^2, y^2], computed in the Magnus embedding
#         W -> F2[Q]^2 x| Q, Q = Z4 x Z4.
#   E4  : finite groups with an elementary abelian normal N and G/N = Z4: for every phi : F2 -> Z4 onto,
#         the universal one is F2[Z4]^2 x| Z4 (Magnus), a subgroup of (Z2 wr Z4)^2, so E4 adds nothing
#         to WR; checked below.
import os
_src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "aabb_variety.py")).read()
exec(_src[:_src.index("Ma, Mb = E(")])  # helpers and BD (all homs F2 -> Z2 wr Z4) from aabb_variety.py

def subgroup_functionals(Gp, gens_list):
    B = []
    for X, Y in gens_list: B = add_all(B, coords(Gp, schreier_vals(Gp, X, Y)))
    return B

# UT4(F2): 4x4 upper unitriangular, rows as bitmasks
I4 = tuple(1 << i for i in range(4))
def minv4(A):
    N = tuple(A[i] ^ (1 << i) for i in range(4)); P = I4; R = list(I4)
    for _ in range(4):
        P = mmul(P, N); R = [r ^ p for r, p in zip(R, P)]
    return tuple(R)
class UT4:
    one = I4; mul = staticmethod(mmul); inv = staticmethod(minv4)
UTE = []
for bits in range(64):
    M = list(I4); k = 0
    for i in range(4):
        for j in range(i + 1, 4):
            if bits >> k & 1: M[i] |= 1 << j
            k += 1
    UTE.append(tuple(M))
BD_UT = subgroup_functionals(UT4, [(X, Y) for X in UTE for Y in UTE])
BD_WR = BD

# Magnus embedding of W: elements (f, q), f in F2[Q]^2 as a 32-bit int (bit 16*c + 4*i + j), q = (i, j).
def qshift(q, f):
    g = 0
    for c in range(2):
        for i in range(4):
            for j in range(4):
                if f >> (16 * c + 4 * i + j) & 1:
                    g |= 1 << (16 * c + 4 * ((i + q[0]) % 4) + (j + q[1]) % 4)
    return g
class Mag:
    one = (0, (0, 0))
    @staticmethod
    def mul(x, y): return (x[0] ^ qshift(x[1], y[0]), ((x[1][0] + y[1][0]) % 4, (x[1][1] + y[1][1]) % 4))
    @staticmethod
    def inv(x):
        q = ((-x[1][0]) % 4, (-x[1][1]) % 4)
        return (qshift(q, x[0]), q)
xg, yg = (1, (1, 0)), (1 << 16, (0, 1))
sv = [v[0] for v in schreier_vals(Mag, xg, yg)]
assert all(v[1] == (0, 0) for v in schreier_vals(Mag, xg, yg))
# coordinates of a base vector in the Schreier basis (solve over F2)
piv = {}
for i, v in enumerate(sv):
    m = 1 << i
    while v:
        h = v.bit_length() - 1
        if h in piv: v ^= piv[h][0]; m ^= piv[h][1]
        else: piv[h] = (v, m); break
print("Magnus: rank of M in F2[Q]^2:", len(piv), "(17 means faithful)")
def schreier_coords(v):
    m = 0
    while v:
        h = v.bit_length() - 1
        assert h in piv, "not in M"
        v ^= piv[h][0]; m ^= piv[h][1]
    return m
x2, y2 = Mag.mul(xg, xg), Mag.mul(yg, yg)
comm = Mag.mul(Mag.mul(x2, y2), Mag.inv(Mag.mul(y2, x2)))
assert comm[1] == (0, 0)
gensK = [qshift((2, 0), v) ^ v for v in sv] + [qshift((0, 2), v) ^ v for v in sv] + \
        [qshift((i, j), comm[0]) for i in range(4) for j in range(4)]
KFA = add_all([], [schreier_coords(v) for v in gensK])
print("FA: dim of M cap Phi(W)' =", len(KFA), "; functionals of FA family: rank", 17 - len(KFA))

def kernel_of(funcs, within):
    # subspace of span(within) killed by all funcs
    vs = [(v, 1 << k) for k, v in enumerate(within)]
    rows = []  # each vector -> its evaluation pattern
    out = []
    basis = []
    for v, _ in vs:
        ev = sum((bin(f & v).count("1") & 1) << i for i, f in enumerate(funcs))
        basis.append((ev, v))
    # Gaussian elimination on ev, tracking v
    piv2 = {}
    for ev, v in basis:
        while ev:
            h = ev.bit_length() - 1
            if h in piv2: ev ^= piv2[h][0]; v ^= piv2[h][1]
            else: piv2[h] = (ev, v); break
        if ev == 0 and v: out.append(v)
    return add_all([], out)
FULL = [1 << i for i in range(17)]
def in_var(func_lists, K_extra, gfun):
    funcs = [f for L in func_lists for f in L]
    K = kernel_of(funcs, K_extra if K_extra is not None else FULL)
    return all(bin(g & k).count("1") % 2 == 0 for g in gfun for k in K), len(K)

# E4 universal groups for phi onto Z4, inside the WR span?
def mk_e4(phx, phy):
    def sh(s, f):
        g = 0
        for c in range(2):
            for i in range(4):
                if f >> (4 * c + i) & 1: g |= 1 << (4 * c + (i + s) % 4)
        return g
    class E:
        one = (0, 0)
        @staticmethod
        def mul(x, y): return (x[0] ^ sh(x[1], y[0]), (x[1] + y[1]) % 4)
        @staticmethod
        def inv(x): return (sh((-x[1]) % 4, x[0]), (-x[1]) % 4)
    return E, (1, phx), (1 << 4, phy)
BD_E4 = []
for phx in range(4):
    for phy in range(4):
        if phx % 2 or phy % 2:
            E, X, Y = mk_e4(phx, phy)
            BD_E4 = add_all(BD_E4, coords(E, schreier_vals(E, X, Y)))
print("E4: rank", len(BD_E4), "; inside span of WR:", all(reduce(BD_WR, f) == 0 for f in BD_E4))
print("UT4(F2): rank", len(BD_UT), "; WR + UT rank", len(add_all(BD_WR, BD_UT)))

# syntactic groups of the single letter-in-state counts on Z4 x Z2 (as in aabb_variety.py (4))
top = [(i, j) for i in range(4) for j in range(2)]
T, idx = mk_wr(top, lambda s, t: ((s[0] + t[0]) % 4, (s[1] + t[1]) % 2))
def closure(gens):
    seen = {T.one}; fr = [T.one]
    while fr: fr = [y for x in fr for g in gens for y in [T.mul(x, g)] if y not in seen and not seen.add(y)]
    return seen
def syntactic(x, g):
    X = (1 if x == "a" else 0, (1, 0)); Y = (1 if x == "b" else 0, (0, 1))
    G = closure([X, Y])
    F = {t for t in G if t[0] >> idx[g] & 1}
    stab = {n for n in G if all(T.mul(e, n) in F for e in F)}
    N = [n for n in stab if all(T.mul(T.mul(T.inv(p), n), p) in stab for p in G)]
    rep = {}
    for t in G:
        if t not in rep:
            cos = [T.mul(t, n) for n in N]; m = min(cos)
            for e in cos: rep[e] = m
    class Q:
        one = rep[T.one]
        mul = staticmethod(lambda a, b: rep[T.mul(a, b)])
        inv = staticmethod(lambda a: rep[T.inv(a)])
    return len(G) // len(N), coords(Q, schreier_vals(Q, rep[X], rep[Y]))

for x, g in [("b", (0, 1)), ("a", (0, 0)), ("b", (2, 1)), ("b", (3, 1))]:
    order, gf = syntactic(x, g)
    r = []
    for name, fl, K in [("WR", [BD_WR], None), ("UT", [BD_UT], None), ("WR+UT", [BD_WR, BD_UT], None),
                        ("FA", [], KFA), ("WR+FA", [BD_WR], KFA), ("WR+UT+FA", [BD_WR, BD_UT], KFA)]:
        ok, dk = in_var(fl, K, gf)
        r.append((name, ok, dk))
    print("count of", x, "at", g, ": |syntactic group|", order, "; rank on M", len(gf),
          "; (family, in variety, dim of common kernel):", r)
